<?php
declare(strict_types=1);
require dirname(__DIR__).'/lib.php';require dirname(__DIR__).'/auth.php';require dirname(__DIR__).'/campaigns.php';
function check($ok,$msg){if(!$ok)throw new RuntimeException($msg);echo "OK $msg\n";}
$key=str_repeat('a',32);$secret='whsec_'.base64_encode($key);$ts=(string)time();$sid='msg_test';$id='12345678-abcd-4321-aaaa-123456789abc';$mail='contact@example.org';$address='dual@example.org';
$d=seed(json_decode(file_get_contents(__DIR__.'/fixture.json'),true,512,JSON_THROW_ON_ERROR));camp_init($d);$cid='2026-2027';$eid=array_key_first($d['companies']);$d['companies'][$eid]['emails']=$mail;
$d['inbox_config']=['enabled'=>true,'secret'=>$secret,'key'=>'re_test','address'=>$address];
$event=['type'=>'email.received','data'=>['email_id'=>$id,'from'=>'Empresa <'.$mail.'>','to'=>[$address],'subject'=>'Respuesta de prueba']];$raw=json_encode($event);$sig='v1,'.base64_encode(hash_hmac('sha256',$sid.'.'.$ts.'.'.$raw,$key,true));
check(ib_signature($raw,$sid,$ts,$sig,$secret),'firma válida');check(!ib_signature($raw.' ',$sid,$ts,$sig,$secret),'rechaza cuerpo alterado');check(!ib_signature($raw,$sid,$ts,$sig,'whsec_'.base64_encode(str_repeat('b',32))),'rechaza clave incorrecta');check(!ib_signature($raw,$sid,$ts,$sig,$secret,(int)$ts+301),'rechaza evento caducado');check(ib_signature($raw,$sid,$ts,'v1,bad '.$sig,$secret),'admite rotación de firmas');
$wrong=$event;$wrong['data']['to']=['other@example.org'];check(ib_ingest($d,$wrong)===200&&empty($d['inbox']),'ignora otro destinatario');$bad=$event;$bad['data']['email_id']='../../etc/passwd';check(ib_ingest($d,$bad)===400,'rechaza identificador inválido');
check(ib_ingest($d,$event)===200&&count($d['inbox'])===1,'encola evento');check(ib_ingest($d,$event)===200&&count($d['inbox'])===1,'evento repetido idempotente');check(ib_matching($d,$mail)===[$eid],'sugiere empresa');check(ib_hold($d,$mail,$eid),'retiene seguimiento');check(!ib_hold($d,'otra@example.org',$eid),'no retiene otros correos');
$m=&$d['inbox'][$id];check(!ib_store_body($m,['from'=>'forged@example.org','text'=>'x']),'comprueba remitente recuperado');check(ib_store_body($m,['from'=>$mail,'html'=>'<b>Hola</b>','authentication'=>['dmarc'=>'pass'],'attachments'=>[['filename'=>'informe.pdf']]])&&$m['body']==='Hola'&&$m['dmarc']==='pass'&&$m['attachments']===['informe.pdf'],'recuperación simulada, texto y metadatos de adjuntos');check(ib_store_body($m,['from'=>$mail,'text'=>str_repeat('á',15000)])&&$m['truncated']&&strlen($m['body'])===24000,'limita texto sin romper UTF-8');
$dir=sys_get_temp_dir().'/fpdual-inbox-'.uid();mkdir($dir,0700);$_SESSION=['role'=>'admin'];$_SERVER['REMOTE_ADDR']='127.0.0.1';$cfg=['mail_mode'=>'test','https_required'=>false,'public_url'=>'http://localhost','admin_email'=>'admin@example.org'];
try{
$d['settings']['public']=true;$d['campaign_settings']['enabled']=true;$d['campaign_permissions'][$eid][$mail]=['allowed'=>true];$d['links'][$cid][$eid]['status']='Contactada';$d['links'][$cid][$eid]['confirmed']=0;$d['campaigns']['c']=['course'=>$cid,'name'=>'Test','subject'=>'Test','body'=>'Hola','follow'=>true,'follow_body'=>'Seguimiento','follow_days'=>5,'state'=>'active','rows'=>[$eid=>['email'=>$mail,'state'=>'sent','due'=>0,'follow_state'=>'pending','follow_due'=>time()-1,'attempts'=>1,'history_count'=>count($d['links'][$cid][$eid]['history'])]]];camp_tick($d,$cfg,$dir);check($d['campaigns']['c']['rows'][$eid]['follow_state']==='pending'&&!file_exists($dir.'/mail-test.jsonl'),'buzón retiene envío automático sin gastar intento');
$_POST=['id'=>$id];ib_action('ib_archive',$d,$cfg,$dir);check(!ib_hold($d,$mail,$eid),'archivar libera retención');ib_action('ib_reopen',$d,$cfg,$dir);check(ib_hold($d,$mail,$eid),'reabrir retiene');
$_POST=['id'=>$id,'course'=>$cid,'link'=>$eid,'note'=>'Respuesta revisada'];ib_action('ib_link',$d,$cfg,$dir);check($m['state']==='linked'&&$m['link']===$eid,'vinculación explícita');check($d['links'][$cid][$eid]['confirmed']===0,'no confirma plazas');camp_tick($d,$cfg,$dir);check($d['campaigns']['c']['rows'][$eid]['follow_state']==='skipped','historial cancela seguimiento previo');
$m['dmarc']='pass';$_POST=['id'=>$id,'confirm'=>'yes','reply_revision'=>'0','subject'=>'Re: prueba','body'=>'Gracias por su respuesta'];ib_action('ib_reply',$d,$cfg,$dir);check(count($m['replies'])===1&&array_values($m['replies'])[0]['state']==='sent','respuesta manual simulada');
$_POST=['id'=>$id,'confirm'=>'yes'];ib_action('ib_delete',$d,$cfg,$dir);check(!isset($d['inbox'][$id])&&isset($d['inbox_deleted'][$id]),'borrado conserva identificador para deduplicar');check(ib_ingest($d,$event)===200&&!isset($d['inbox'][$id]),'evento repetido no resucita mensaje');
}finally{foreach(glob($dir.'/*') as $f)unlink($f);rmdir($dir);}
